CREATE TABLE accounts (id VARCHAR(64) PRIMARY KEY, version BIGINT NOT NULL, email VARCHAR(12000) NOT NULL, password_hash VARCHAR(12000) NOT NULL, display_name VARCHAR(12000) NOT NULL, role VARCHAR(12000) NOT NULL, seller_status VARCHAR(12000) NOT NULL, bio VARCHAR(12000) NOT NULL, language VARCHAR(12000) NOT NULL, interests VARCHAR(12000) NOT NULL);
CREATE TABLE products (id VARCHAR(64) PRIMARY KEY, version BIGINT NOT NULL, seller_id VARCHAR(12000) NOT NULL, title VARCHAR(12000) NOT NULL, description VARCHAR(12000) NOT NULL, category VARCHAR(12000) NOT NULL, price_won INTEGER NOT NULL, term_days INTEGER NOT NULL, status VARCHAR(12000) NOT NULL, thumbnail VARCHAR(12000) NOT NULL, media_key VARCHAR(12000) NOT NULL, preview_key VARCHAR(12000) NOT NULL, duration_seconds DOUBLE PRECISION NOT NULL, kind VARCHAR(12000) NOT NULL, bundle_ids VARCHAR(12000) NOT NULL, blocked BOOLEAN NOT NULL, created_at BIGINT NOT NULL);
CREATE TABLE purchases (id VARCHAR(64) PRIMARY KEY, version BIGINT NOT NULL, buyer_id VARCHAR(12000) NOT NULL, request_key VARCHAR(12000) NOT NULL, status VARCHAR(12000) NOT NULL, channel VARCHAR(12000) NOT NULL, created_at BIGINT NOT NULL);
CREATE TABLE order_lines (id VARCHAR(64) PRIMARY KEY, version BIGINT NOT NULL, purchase_id VARCHAR(12000) NOT NULL, buyer_id VARCHAR(12000) NOT NULL, seller_id VARCHAR(12000) NOT NULL, product_id VARCHAR(12000) NOT NULL, title VARCHAR(12000) NOT NULL, price_won INTEGER NOT NULL, channel_fee_won INTEGER NOT NULL, platform_fee_won INTEGER NOT NULL, seller_amount_won INTEGER NOT NULL, term_days INTEGER NOT NULL, refunded BOOLEAN NOT NULL, settlement_id VARCHAR(12000) NOT NULL);
CREATE TABLE grants (id VARCHAR(64) PRIMARY KEY, version BIGINT NOT NULL, buyer_id VARCHAR(12000) NOT NULL, product_id VARCHAR(12000) NOT NULL, line_id VARCHAR(12000) NOT NULL, expires_at BIGINT NOT NULL, revoked BOOLEAN NOT NULL);
CREATE TABLE engagements (id VARCHAR(64) PRIMARY KEY, version BIGINT NOT NULL, user_id VARCHAR(12000) NOT NULL, target_id VARCHAR(12000) NOT NULL, kind VARCHAR(12000) NOT NULL, content VARCHAR(12000) NOT NULL, number_value DOUBLE PRECISION NOT NULL, updated_at BIGINT NOT NULL);
CREATE TABLE tickets (id VARCHAR(64) PRIMARY KEY, version BIGINT NOT NULL, user_id VARCHAR(12000) NOT NULL, target_id VARCHAR(12000) NOT NULL, recipient_id VARCHAR(12000) NOT NULL, kind VARCHAR(12000) NOT NULL, message VARCHAR(12000) NOT NULL, status VARCHAR(12000) NOT NULL, reply VARCHAR(12000) NOT NULL, created_at BIGINT NOT NULL);
CREATE TABLE notices (id VARCHAR(64) PRIMARY KEY, version BIGINT NOT NULL, user_id VARCHAR(12000) NOT NULL, message VARCHAR(12000) NOT NULL, read BOOLEAN NOT NULL, created_at BIGINT NOT NULL);
CREATE TABLE audits (id VARCHAR(64) PRIMARY KEY, version BIGINT NOT NULL, actor_id VARCHAR(12000) NOT NULL, action VARCHAR(12000) NOT NULL, target_id VARCHAR(12000) NOT NULL, detail VARCHAR(12000) NOT NULL, created_at BIGINT NOT NULL);
CREATE TABLE login_sessions (id VARCHAR(64) PRIMARY KEY, version BIGINT NOT NULL, user_id VARCHAR(12000) NOT NULL, token_hash VARCHAR(12000) NOT NULL, expires_at BIGINT NOT NULL);
CREATE TABLE settlements (id VARCHAR(64) PRIMARY KEY, version BIGINT NOT NULL, seller_id VARCHAR(12000) NOT NULL, amount_won INTEGER NOT NULL, created_at BIGINT NOT NULL);
CREATE UNIQUE INDEX ux_account_email ON accounts(email);
CREATE UNIQUE INDEX ux_request ON purchases(buyer_id, request_key);
CREATE UNIQUE INDEX ux_engagement ON engagements(user_id, target_id, kind);
CREATE UNIQUE INDEX ux_session ON login_sessions(token_hash);
CREATE INDEX ix_grants_buyer ON grants(buyer_id, product_id);
CREATE INDEX ix_lines_purchase ON order_lines(purchase_id);
CREATE INDEX ix_product_seller ON products(seller_id);
CREATE INDEX ix_notice_user ON notices(user_id);
CREATE INDEX ix_ticket_user ON tickets(user_id);
